"""Create editable author-review documents from the frozen analysis outputs."""
from pathlib import Path
import csv, json, re
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[1]
R=json.loads((ROOT/'results/results.json').read_text(encoding='utf-8'))
S=json.loads((ROOT/'inputs/sentences.json').read_text(encoding='utf-8'))
OUT=ROOT/'documents';OUT.mkdir(exist_ok=True)
def pick(config,sentence,var='CMRO2'):
    return next(x for x in R['summary'] if x['config']==config and x['sentence']==sentence and x['variable']==var)
def num(x): return f'{x:.5f}'
def interval(x): return f"{num(x['lower'])} to {num(x['upper'])}"
primary=[pick('primary',s) for s in S]
ref=[x for x in R['consistency'] if x['kind']=='reference_leave_file_out']
co=[x for x in R['consistency'] if x['kind']=='composite']
q=list(csv.DictReader((ROOT/'results/signal_quality.csv').open()))

def document(title,blocks,name,manuscript=False):
    d=Document();sec=d.sections[0];sec.top_margin=sec.bottom_margin=Inches(.8);sec.left_margin=sec.right_margin=Inches(.85)
    for style in ['Normal','Title','Heading 1','Heading 2','Heading 3']:
        st=d.styles[style];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
        st.font.size=Pt(11 if style=='Normal' else (16 if style=='Title' else 12))
        st.paragraph_format.space_after=Pt(6);st.paragraph_format.line_spacing=1.15
        ppr=st.element.find(qn('w:pPr'))
        if ppr is not None:
            for border in list(ppr.findall(qn('w:pBdr'))):ppr.remove(border)
    # Template theme styles can inherit a title border from Normal.
    for st in d.styles:
        ppr=st.element.find(qn('w:pPr'))
        if ppr is not None:
            for border in list(ppr.findall(qn('w:pBdr'))):ppr.remove(border)
    d.add_paragraph(title,'Title')
    d.add_paragraph('Working revision 1.27 • 3 October 2026 • Author verification required')
    md=['# '+title,'','Working revision 1.27 — 3 October 2026 — Author verification required','']
    for kind,data in blocks:
        if kind=='h':d.add_paragraph(data,'Heading 1');md.extend(['## '+data,''])
        elif kind=='sub':d.add_paragraph(data,'Heading 2');md.extend(['### '+data,''])
        elif kind=='p':d.add_paragraph(data);md.extend([data,''])
        elif kind=='note':
            p=d.add_paragraph();rr=p.add_run(data);rr.bold=True;md.extend(['**'+data+'**',''])
        elif kind=='table':
            caption,heads,rows=data;d.add_paragraph(caption,'Heading 2');t=d.add_table(rows=1,cols=len(heads));t.style='Table Grid'
            for j,h in enumerate(heads):t.rows[0].cells[j].text=str(h)
            trpr=t.rows[0]._tr.get_or_add_trPr();repeat=OxmlElement('w:tblHeader');trpr.append(repeat)
            for row in rows:
                cells=t.add_row().cells
                for j,value in enumerate(row):cells[j].text=str(value)
            for row in t.rows:
                pr=row._tr.get_or_add_trPr();pr.append(OxmlElement('w:cantSplit'))
                for cell in row.cells:
                    for p in cell.paragraphs:
                        p.paragraph_format.space_after=Pt(3);p.paragraph_format.line_spacing=1
                        for run in p.runs:run.font.size=Pt(9)
            md.extend(['### '+caption,'','| '+' | '.join(heads)+' |','| '+' | '.join(['---']*len(heads))+' |'])
            md.extend('| '+' | '.join(str(v).replace('|','/') for v in row)+' |' for row in rows);md.append('')
        elif kind=='figure':
            fn,caption=data;d.add_picture(str(ROOT/'figures'/fn),width=Inches(6.5));d.add_paragraph(caption);md.extend(['!['+caption+'](../figures/'+fn+')','',caption,''])
        elif kind=='page':d.add_page_break()
    footer=sec.footer.paragraphs[0];footer.alignment=2
    footer.add_run('Working revision • ');fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');footer._p.append(fld)
    d.core_properties.title=title;d.core_properties.author='';d.core_properties.subject='Round two manuscript revision for author review'
    d.save(OUT/(name+'.docx'));(OUT/(name+'.md')).write_text('\n'.join(md),encoding='utf-8')

blocks=[]
def add(k,v):blocks.append((k,v))
add('p','Gowrish Rajagopal¹, Aniket Chaudhari¹, John LaRocco²*, Jinyi Xue³, Eric Zachariah¹, Shwetan Varanasi¹, and Douglas Rothman⁴')
add('p','¹ College of Engineering, Ohio State University, Columbus, OH, USA. ² Ronin Institute for Independent Scholarship 2.0, Sacramento, CA, USA. ³ College of Arts and Sciences, Ohio State University, Columbus, OH, USA. ⁴ School of Medicine, Yale University, New Haven, CT, USA.')
add('p','*Corresponding author: john.larocco@ronininsitute.org. Author names, affiliations, and contact are retained from version 1.26 and require author confirmation.')
add('note','AUTHOR REVIEW NOTICE: This replacement draft reports a new exploratory reanalysis. Confirm the acquisition channel order, stimulus protocol and crosswalk, participant provenance, ethics and reuse terms, and public release identifier before submission. The local package has not been deposited or submitted.')
add('h','Abstract')
add('p',f'Text-driven assembly of recorded electroencephalographic (EEG) segments offers a controllable way to examine how composition choices propagate through a physiological simulation. We revised a framework that links a retrieval-augmented language model to pronunciation lookup, EEG assembly, spectral features, and illustrative neurovascular outputs. An audit of 44 source files recovered 220 paired event intervals, identified a packet counter previously used as an event anchor, and exposed a mismatch between the application file order and the public stimulus order. The replacement analysis used marked task intervals at a nominal 250 Hz and compared three fixed texts with and without inserted segments from recorded instructed-wait intervals. Across 2,000 seeded realizations per text, mean changes in a normalized gamma index were {primary[0]["mean"]:.4f}, {primary[1]["mean"]:.4f}, and {primary[2]["mean"]:.4f}; their central 95% simulation intervals were [{primary[0]["lower"]:.4f}, {primary[0]["upper"]:.4f}], [{primary[1]["lower"]:.4f}, {primary[1]["upper"]:.4f}], and [{primary[2]["lower"]:.4f}, {primary[2]["upper"]:.4f}]. These intervals describe algorithmic variation rather than uncertainty about a population effect. Comparisons with separate trials from the same recording set showed similar coarse spectral and channel profiles but variable source-space agreement. Duration controls, alternate mappings, and normalization choices changed the effect estimates. The framework therefore demonstrates reproducible propagation of assembly choices through a model. Validation against continuously recorded imagined sentences, independently measured metabolism, and verified acquisition metadata remains necessary.')
add('p','Keywords: imagined speech; electroencephalography; text-guided simulation; neurovascular modeling; reproducibility; sensitivity analysis')
add('h','1 Introduction')
add('p','Imagined speech research examines neural activity associated with internally produced speech. In a decoding experiment, a model uses neural measurements to infer an utterance or a linguistic property. Studies of EEG phoneme classification and noninvasive language reconstruction establish relevant measurement and evaluation problems [1,2]. The present framework instead starts with known text and uses its pronunciation to select recorded EEG segments. Its output is a constructed signal whose linguistic order is supplied by the text. No decoder accuracy or recovery of an unknown utterance is evaluated.')
add('p','This distinction matters because a segment associated with an isolated speech cue need not preserve its neural response when placed next to other segments. Continuous sentence production contains contextual, timing, and coarticulatory effects that simple concatenation does not model. Inserting additional segments can change spectral summaries by changing the sample composition and duration. Such a change alone does not establish a more realistic biological signal.')
add('p','A second distinction concerns physiological interpretation. The software maps a normalized EEG gamma feature onto a selected oxygen-consumption scale and then applies algebraic relations inspired by a neurovascular homeostasis model [3]. Those relations allow the propagation of an assumed driver through a consistent set of outputs. They do not calibrate scalp gamma power to oxygen consumption or measure blood flow, tissue pH, gas tensions, or lactate. All resulting quantities remain conditional on the imposed mapping and constants.')
add('p','The purpose of this study is to characterize the computational behavior and limitations of this framework. We ask how inserting recorded waiting-period segments changes a primary normalized gamma index, whether the change depends on assembly and scaling choices, and how constructed signals compare with separate source trials in spectral, source-space, and model-derived channel profiles. A provenance audit and a replacement numerical analysis address defects identified during peer review. We use descriptive simulation summaries and make the distinction between algorithmic replication and biological replication explicit.')
add('h','2 Materials and methods')
add('sub','2.1 Source recordings and provenance')
add('p','The local recording set comprises 44 files named DLR_0_1.txt through DLR_43_1.txt. Every file contains 32 columns. After converting CRLF line endings to LF for comparison, the Git blob hash of each local file matches a file in the public ghostTalkerAlpha repository at commit 40fe0cf64e79916ced50cb82d7d0ee03f77b41c3, including the directory TestData/DLR_Tests/3-21-2023 [4]. This establishes file provenance and does not independently establish participant identity. The previous manuscript describes a single-participant subset; the exact participant linkage and reuse authorization require confirmation from the data custodian.')
add('p','Column 0 takes values from 0 to 255 and repeatedly wraps to zero. It is a packet counter, not an event-time coordinate. Column 30 contains timestamps, and column 31 contains two occurrences each of markers 1 through 5. The archived acquisition script inserts the same marker at the beginning and end of each instructed two-second imagined-speech interval. We therefore record each start and end row explicitly and extract the first 250 samples following each start for the present analysis. These one-second blocks are analysis selections within marked trials, not additional independent trials.')
add('p',f'The original publication and the archived Wi-Fi acquisition script specify a nominal sampling rate of 250 Hz [1,4]. Across the 220 marker pairs in the local files, the median ratio of sample count to timestamp duration is {R["audit"]["rate_median"]:.2f} samples/s. Individual ratios range from {R["audit"]["rate_range"][0]:.2f} to {R["audit"]["rate_range"][1]:.2f}; timestamp delivery irregularity and possible packet loss must be distinguished before biological interpretation. The repeating 256-value counter does not establish a 256 Hz sampling rate. The replacement analysis uses the documented nominal 250 Hz rate.')
add('p','The application assigns the first 39 files to an alphabetical ARPAbet inventory and uses files 39–43 as auxiliary segments. The public acquisition script and stimulus slides use a different order. For example, slide index 0 illustrates the vowel in feel/read, index 28 illustrates B, and indices 39–43 illustrate NG, R, L, W, and Y. The replacement crosswalk follows the archived slides. AH0 is mapped to the again/under stimulus and stressed AH to nut/cut. AA and AO use the dark/are and roar/morning stimuli. These mappings involve dialect approximations and are not evidence of a validated phoneme decoder. The applicable acquisition version and physical electrode-to-column order remain author verification items.')
add('sub','2.2 Language model and frozen text inputs')
add('p','The desktop application obtains responses from a retrieval-augmented conversational model using an interview/autobiography corpus. The corpus is split into 500-character chunks with 50-character overlap, embedded using text-embedding-3-large, and retrieved through a FAISS index. The configured response model is gpt-4-0125-preview. Retrieved text and conversation context guide the response; the software does not fine-tune the model weights on the autobiography. The model configuration describes the application, while the numerical experiment uses the three existing responses in Table 1 and makes no new model calls.')
add('p','The full texts were frozen from the supplied version 1.26 manuscript. Their lengths exceed the response prompt’s stated 20-word target, so we do not claim that this limit was enforced in these examples. The texts are illustrative software inputs. Their content is not a measured autobiographical response or a clinical or cognitive outcome.')
add('table',('Table 1 Frozen text inputs',['Input','Prompt','Recorded response'],[[sn,t['prompt'],t['response']] for sn,t in S.items()]))
add('sub','2.3 Pronunciation lookup and assembly')
add('p','Pronunciations were taken from CMUdict at commit 74790861f652b15e4ac49015a90074ad62a27690 [5]. The package stores the exact entries used, the dictionary hash, and its license. The first dictionary pronunciation was selected. BCIs was explicitly expanded as the letters B C I followed by plural Z; streetside was expanded by concatenating the entries for street and side. These two declared editorial pronunciations require author confirmation. Missing entries cause an error rather than silently removing words. No probabilistic pronunciation fixture or unrecorded grapheme-to-phoneme fallback is used in the replacement results.')
add('p','A common word tokenizer preserves internal apostrophes and supplies the same word and phoneme stream to both conditions. The primary assembly places one 250-sample marked task block per phoneme in text order. Trial 2 supplies every task block used in a composite. Repeated occurrences of a phoneme reuse that block; they therefore remain repeated samples from one recorded trial. Stress annotations inform the explicit AH crosswalk but do not create additional EEG classes.')
add('p','In the insertion condition, each boundary between words receives either one or two one-second intertrial blocks with equal probability. Each block is sampled uniformly from the 44 available files. The block begins 50 samples after the end marker of trial 2 and ends 300 samples after that marker; every selected block is verified to precede the next task marker. The protocol instructs waiting between trials, but no separate marker identifies the exact onset of the wait screen. The selected blocks may therefore contain cue-switching or neural carryover effects and should not be treated as a verified resting baseline. A two-second insertion comprises two sampled one-second blocks. These are intertrial selections from an instructed-wait protocol, not naturally timed pauses from continuous sentences. Punctuation does not create extra gaps. Each realization uses its integer seed with NumPy’s default generator; seeds 0–1999 form the primary simulation ensemble.')
add('p','Calibration uses trial 1 task and wait blocks. Construction uses trial 2 blocks. Reference comparisons use task blocks from trials 3–5. These roles share a recording session and a participant source; separating them prevents sample reuse between construction and reference but does not create an independent biological cohort. Row-level event tables and seed-0 assembly manifests are supplied with the numerical outputs.')
add('sub','2.4 Spectral feature and primary normalized index')
add('p','Each one-second block is divided into two nonoverlapping 125-sample windows. SciPy computes a periodic-Hann, constant-detrended power spectral density with nperseg = 125, noverlap = 0, and density scaling. This is a single tapered periodogram per window, rather than an average over overlapping subwindows. Frequency spacing is 2 Hz. Gamma power is the sum of PSD values for 30 ≤ f < 100 Hz multiplied by the 2 Hz bin width. No window crosses an assembly boundary. Short and final blocks are not discarded by a four-second grouping rule.')
add('p',f'The primary dimensionless index is u = clip[(G − a)/(b − a), 0, 1], where G is gamma power and a and b are the first and 99th percentiles of the trial-1 calibration windows pooled across task, wait, files, and channels. The recorded bounds are a = {R["bounds"][0]:.6g} and b = {R["bounds"][1]:.6g} in squared stored-signal units. Each composite is summarized by the mean of u over windows and 16 channels. Channels are repeated spatial measurements rather than independent biological replicates. Clipping and raw-signal quality diagnostics are reported in the supplementary numerical package.')
add('p','The primary analysis applies no artifact rejection or line-noise removal; this choice preserves the auditable stored signals but limits physiological interpretation. Window detrending removes a constant within each window, not muscle activity, movement artifacts, drift within a window, or line noise. A 30–45 Hz sensitivity analysis avoids the 60 Hz neighborhood while retaining the same construction design and recalculating its calibration bounds. This sensitivity cannot establish artifact-free neural gamma.')
add('sub','2.5 Illustrative physiological transform')
add('p','For compatibility with the model, the software sets a CMRO2 proxy C = 2.1 + u on an imposed 2.1–3.1 μmol/(g·min) scale. The model driver is the fractional change d = C/2.1 − 1, correcting the earlier use of absolute C as a fractional change. With coupling constant n = 2.28 and baseline oxygen extraction OEF0 = 0.42, OEF = OEF0(1 + d)/(1 + nd) and CBF = C/(6.9·OEF). The latter is in mL/(g·min) under the stated concentration units; multiply by 100 to express mL/(100 g·min). These equations preserve an assumed flow–metabolism relation, not a measured EEG-to-metabolism calibration.')
add('p','The supplied implementation then calculates venous pH, venous pCO2, a Hill-equation capillary oxygen proxy, and CO2- and lactate-associated proton terms using its stored constants. Supplementary Table S1 gives those constants and the executable model records every expression. The implementation is an illustrative adaptation motivated by the homeostasis model of DiNuzzo and colleagues [3]; equation and parameter provenance has not been independently established for every constant. The code field DeltaHCO2 is a modeled flux term and is nonzero at the selected baseline, so it should not be read as an independently measured change from baseline.')
add('p','All eight outputs are deterministic functions of the same scalar d. CBF, CMRO2, and the two flux terms are affine functions of that driver for fixed constants. Their aligned changes therefore do not constitute independent confirmations of an effect. We report u as the primary outcome and retain the transformed values as model outputs in the supporting data. No tissue metabolism measurement was available.')
add('sub','2.6 Simulation summaries and controls')
add('p','For each text, the no-insertion composition is fixed. Each inserted realization is compared with that fixed baseline. We report the ensemble mean difference, standard deviation across realizations, empirical 2.5th and 97.5th percentiles, and Monte Carlo standard error of the ensemble mean, SD/√R. The percentile interval is a central simulation interval for the specified algorithm. It is not a confidence interval for a participant-population effect. The draws vary insertion choices conditional on fixed source recordings; they are not biological replicates. No paired electrode t-test, Wilcoxon test, Cohen’s d across electrodes, or hypothesis-testing p-value is reported.')
add('p','A duration-matched control uses the same insertion counts but fills each added second with a repetition of the preceding word’s final task block. This distinguishes the recorded-wait pool from simply extending duration with selected task data, although both conditions remain synthetic. Sensitivities use 500 realizations per text and separately change normalization to the composite’s own minimum and maximum, the assembly unit to the final phoneme of each word, insertion sources to task files 39–43, the file mapping to the previous application order, or the gamma band to 30–45 Hz. These alternate choices are diagnostics rather than interchangeable estimates of one biological quantity.')
add('p','A window-order control reverses the selected spectral-window sequence while retaining its multiset and normalization bounds. Because the aggregate outputs have no dependence on temporal order and no analysis window crosses a join, their means should remain unchanged within numerical precision. The test identifies what this analysis can measure: sample composition and scale, rather than sentence context, transition smoothness, or a physiological response to pause timing.')
add('sub','2.7 Consistency analyses')
add('p','The held-out within-session reference comprises 132 one-second task blocks from trials 3–5 in the 44 files. The time-frequency analysis compares the mean windowed spectra using correlation of log PSD and root-mean-square log-power difference in dB over 2–100 Hz. Figure 4 also displays short-time spectra of an original continuous source-file fragment and a composite using the same analysis parameters. Their contents and task timing are unmatched; the plot illustrates signal structure and does not test reconstruction accuracy.')
add('p',f'The source-space diagnostic uses a homogeneous sphere with {R["source_count"]} radial shell sources and fixed electrode coordinates inherited from the supplied analysis code. All compared inputs undergo mean removal within each 250-sample block and average referencing. One empirical covariance estimated from trial-1 task and wait blocks defines a common depth-weighted, noise-normalized minimum-norm operator with depth parameter 0.8 and regularization 1/9. Mean squared transformed amplitude defines a source power map; its Spearman correlation with the reference map is reported. This simplified inverse is a sensitivity model. It is not the application’s fsaverage cortical BEM, is not anatomically validated, and remains conditional on verification of electrode-to-column assignments. Source maps should not be interpreted as localizing language function.')
add('p','The model-output consistency measure compares 16-channel mean normalized-gamma profiles on the common calibration scale, using Spearman correlation and mean absolute index difference. The corresponding CMRO2 proxy is an affine rescaling and has the same rank correlation. Calling this a comparison with real metabolism would be incorrect: both profiles are computed from EEG by the same imposed model.')
add('p','For descriptive context, the mean reference profile for each file is compared with the mean of the other 43 files, using the held-out task blocks. The resulting range is not a null distribution or an equivalence margin. A high correlation, including one above the observed reference range, does not demonstrate equivalence or statistical indistinguishability. Seed 0 provides the displayed composite comparisons; all Monte Carlo draws are retained for the primary insertion analysis.')
add('sub','2.8 Software verification and version control')
add('p',f'The replacement analysis package is designated round2-v1.27-working. It records input hashes, event rows, pronunciation entries, assembly plans, every simulation draw, summary tables, and figure inputs. The current run passed {len(json.loads((ROOT/"results/checks.json").read_text()))} recorded numerical checks, including cached-versus-materialized features and aggregate invariance to window order. These checks establish specific computational properties, not biological validity. This batch reanalysis replaces all numerical tables in the prior draft; it is not a claim that the desktop GUI or historical MNE animations have been regenerated or validated. No historical animation is used as quantitative evidence in this revision.')
add('sub','2.9 AI assistance in revision and analysis development')
add('p','OpenAI Codex assisted with manuscript and code auditing, source-metadata retrieval, development of the replacement analysis and plotting scripts, and drafting of revised prose and the reviewer response. The scripts were executed on the supplied recordings; plots were rendered from recorded inputs and calculated outputs using standard plotting software. No generative image model created the research figures. [AUTHOR COMPLETE: describe how the authors independently checked the code, numerical results, sources, figures, and interpretations and approved the revised content. Automated checks in the working package do not substitute for author verification.] This disclosure is included for review under the PLOS AI-use policy: https://journals.plos.org/plosone/s/ethical-publishing-practice#loc-artificial-intelligence-tools-and-technologies.')
add('h','3 Results')
add('sub','3.1 Provenance and event audit')
add('p','All 44 files contained five paired event intervals. In every file, the first 512 samples selected after the first packet-counter zero ended before the first task start marker. The earlier construction anchor therefore did not select a marked imagined-speech interval. The file-order discrepancy and the selection of speech stimuli as auxiliary gaps provided additional reasons to replace the previous numerical experiment. Table 2 records the auditable changes. They also prevent assigning the old tables’ discrepancies to a single transcription or formatting cause.')
add('table',('Table 2 Data and implementation audit',['Item','Observed evidence','Replacement treatment'],[
['Event selection','44/44 old 512-sample selections precede first task marker','Select first 250 samples after each marked task onset'],
['Sampling','Published/script nominal 250 Hz; packet counter wraps at 256','Use 250 Hz and retain timestamp diagnostics'],
['File order','B is acquisition index 28; application index 6','Archived-slide crosswalk with explicit vowel approximations'],
['Auxiliary files','Acquisition indices 39–43 are NG R L W Y stimuli','Primary insertions use recorded instructed waits'],
['Pronunciation','Missing fixture in supplied v1.26 package','Frozen CMUdict entries and two declared overrides'],
['Replication','One recording-source set and correlated channels','Describe conditional algorithmic variation without biological tests']]))
add('sub','3.2 Changes produced by recorded-wait insertion')
add('p','Table 3 summarizes the primary dimensionless index differences. The mean changes were negative for all three inputs. The interval for S2 was entirely negative under this particular simulation, while those for S1 and S3 crossed zero. This describes the range of insertion outcomes under the fixed recording set and construction rule; it does not establish a statistically significant biological reduction in oxygen consumption.')
add('table',('Table 3 Primary normalized gamma simulation results',['Input','No insertion mean','Mean change','Central 95% simulation interval','MCSE of mean'],[[sn,num(x['base']-2.1),num(x['mean']),interval(x),f'{x["mcse_mean"]:.6f}'] for sn,x in zip(S,primary)]))
add('p',f'The no-insertion compositions contained {primary[0]["base_blocks"]}, {primary[1]["base_blocks"]}, and {primary[2]["base_blocks"]} one-second blocks. Mean inserted lengths were {primary[0]["mean_inserted_blocks"]:.2f}, {primary[1]["mean_inserted_blocks"]:.2f}, and {primary[2]["mean_inserted_blocks"]:.2f} seconds. Mean wait-minus-duration-control differences were {primary[0]["duration_control_delta"]:.5f}, {primary[1]["duration_control_delta"]:.5f}, and {primary[2]["duration_control_delta"]:.5f}. Thus the wait pool and the repeated-task duration control produced different feature mixtures. A comparison that ignores source composition cannot attribute these differences solely to pause duration.')
add('sub','3.3 Sensitivity to assembly and normalization')
add('table',('Table 4 Mean index changes under alternate choices',['Choice','S1','S2','S3','Draws per input'],[[label]+[num(pick(config,s)['mean']) for s in S]+[str(pick(config,'S1')['draws'])] for config,label in [('primary','Recorded waits and fixed calibration'),('own_scale','Own minimum and maximum'),('word_final','Final phoneme per word'),('auxiliary_speech','Task files 39–43 as insertions'),('old_file_order','Previous application mapping'),('low_gamma','Gamma restricted to 30–45 Hz')]]))
add('p','The final-phoneme-only choice yielded substantially larger negative means for S1 and S2 than the primary all-phoneme choice. The previous file order and auxiliary-speech insertion pool yielded different magnitudes and, for some inputs, different mean signs. Restricting the feature to 30–45 Hz preserved the direction of the primary mean changes in this run. The result is therefore conditional on an explicit construction and normalization protocol, rather than an invariant property of the text or a validated physiological effect of microgaps.')
add('p','The aggregate window-order controls passed for every configuration and input. Reordering the same analyzed windows preserved the modeled means. This confirms the absence of temporal-order sensitivity in the reported aggregate outcomes and limits any interpretation involving linguistic context or biological transition smoothing.')
add('sub','3.4 Consistency with separate recorded trials')
add('table',('Table 5 Descriptive consistency for seed 0',['Input and condition','Log PSD r','Log PSD RMSE dB','Sphere source ρ','Index channel ρ','Index channel MAE'],[[x['sentence']+' '+x['condition'],f'{x["logpsd_r"]:.3f}',f'{x["logpsd_rmse_db"]:.3f}',f'{x["source_rho"]:.3f}',f'{x["index_profile_rho"]:.3f}',f'{x["index_profile_mae"]:.4f}'] for x in co]))
add('p',f'Across the displayed composites, log-spectral correlations with the held-out within-session mean ranged from {min(x["logpsd_r"] for x in co):.3f} to {max(x["logpsd_r"] for x in co):.3f}; spectral RMSE ranged from {min(x["logpsd_rmse_db"] for x in co):.3f} to {max(x["logpsd_rmse_db"] for x in co):.3f} dB. Source-map correlations were more variable ({min(x["source_rho"] for x in co):.3f}–{max(x["source_rho"] for x in co):.3f}). Channel-index correlations were high ({min(x["index_profile_rho"] for x in co):.3f}–{max(x["index_profile_rho"] for x in co):.3f}), while nonzero absolute differences remained. These measures address different aspects of the construction and do not jointly establish biological realism.')
add('p','The file-excluded reference comparisons are available row by row in consistency.csv. They quantify variation within this recording set rather than a reference population of imagined sentences. No continuous EEG recording matched to the three full text responses and no independently measured metabolic endpoint were available in the supplied data.')
add('sub','3.5 Signal quality and model dependence')
add('p',f'The fraction of gamma-band power in the 58–62 Hz bins varied substantially by channel. Median fractions over task windows ranged from {min(float(x["median_gamma_fraction_58_62hz"]) for x in q):.3f} to {max(float(x["median_gamma_fraction_58_62hz"]) for x in q):.3f}. Large stored-signal offsets and between-channel amplitude differences also warrant a dedicated acquisition and artifact review. These observations preclude treating the present gamma index as a specific measurement of neural oxygen demand. The 30–45 Hz sensitivity reduces exposure to the line-noise neighborhood but does not resolve all signal-quality concerns.')
add('p','The other seven physiological outputs changed in accordance with their deterministic transform of the same index. Their complete per-realization differences and units are supplied as supporting results. They are not additional independent outcomes or separate validations of the proposed mechanism.')
add('h','4 Discussion')
add('p','The replacement analysis establishes a narrower contribution than the earlier imagined-speech reconstruction framing: a reproducible software workflow for propagating text-guided sample selection through spectral summaries and an illustrative physiological transform. It also shows why provenance and event handling must be part of that workflow. A counter wrap was an inadequate event anchor, and an index inventory was not a verified stimulus crosswalk. These problems change the scientific interpretation even when the resulting plots appear plausible.')
add('p','Recorded-wait insertion changed the primary index in a design-dependent manner. The duration-matched control and sensitivity analyses show that sample composition, repeated task blocks, and the scaling rule matter. The chosen periods were instructed waits in an isolated-phoneme protocol. They do not represent naturally timed pauses between words in the tested sentences, and the synthetic sequence does not implement coarticulation or sentence-context responses. The mean changes cannot therefore be described as enhanced biological variability, a pause-induced metabolic response, or proof of a more realistic reconstructed sentence.')
add('p','The consistency results demonstrate that a constructed signal can resemble its source set in coarse spectral and channel summaries while showing weaker or variable agreement under a source transformation. Common donor characteristics, correlated channels, instrumental effects, and the shared normalization rule can all contribute to high channel-profile correlations. Correlation measures shape agreement and does not test equality of distributions or biological equivalence. The simplified sphere inverse additionally depends on montage assignments and regularization, so its maps are descriptive model outputs rather than anatomical evidence.')
add('p','The physiological transform is useful for exploring the consequences of assumptions, but the gamma-to-CMRO2 mapping requires independent validation. A min–max or percentile scale imposes an absolute range; it does not estimate oxygen consumption from data. Parameters such as the coupling constant and glycolytic ratio may also affect downstream outputs. The selected constants and executable equations are exposed so that future studies can revise them, test parameter sensitivities, and compare predictions with independent physiological measurements. The present paper does not claim such calibration has been completed.')
add('p','The statistical revision avoids counting channels or simulation draws as biological replicates. The simulation ensemble answers a conditional question about choices made by an algorithm on a fixed recording set. Increasing its size reduces Monte Carlo error in that conditional summary but provides no additional participants. An inferential claim about imagined-speech biology would require a defined biological unit, an independently justified null or effect model, and replication at the participant or trial level with appropriate dependence handling.')
add('p','The main limitations are the single recording-source subset described in the prior manuscript, unconfirmed participant linkage and physical channel ordering, dialect approximations in the pronunciation crosswalk, repeated use of fixed task blocks, incomplete artifact assessment, and the lack of matched continuous-sentence EEG and metabolic measurements. A next validation study should record the same utterances and naturally occurring or experimentally controlled pauses across participants; retain synchronized stimulus, EEG, and timing metadata; establish preprocessing before examining effects; and evaluate on participant-separated data. Biological validation of the metabolic outputs requires an independent physiological modality rather than another application of the same EEG transform.')
add('h','5 Conclusions')
add('p','The audited workflow provides an exploratory text-guided EEG composition and neurovascular-modeling demonstration. Marked-trial selection, a documented stimulus crosswalk, frozen pronunciations, and complete simulation outputs make its computations reviewable. Recorded-wait insertion changes the modeled summaries, with magnitudes and signs dependent on assembly choices. The available data do not validate reconstruction of unknown speech, sentence-level biological realism, or quantitative EEG-based metabolism. Those questions remain targets for independent experiments after acquisition and signal-quality verification.')
add('h','Declarations')
add('sub','Ethics and participant provenance')
add('p','This reanalysis uses existing human EEG files and involved no new participant recruitment or acquisition. The source study reports ethics approval IRB 2023H0194 and participant consent [1]. [AUTHOR CONFIRM: identify the data custodian and participant subset, confirm that these files fall under the stated approval and consent, describe any conditions on secondary reuse, and state the applicable institutional determination for this work. Do not infer an exemption from the absence of new recruitment.]')
